"""Generate the case folding table used when link labels are matched.

CommonMark compares link labels after they have been case folded, which is
the *full* Unicode case folding and not the simple lowercasing: `ẞ` folds to
`ss` and not to `ß`.  Python's `str.casefold()` implements that folding, so
the table is generated from the standard library.

Usage: python scripts/generate-casefold.py
"""

from __future__ import annotations

import pathlib

HEADER = """//! The full Unicode case folding of the characters that need more than the
//! simple lowercasing.
//!
//! The table is generated by `scripts/generate-casefold.py`.  Every character
//! that folds to something else than its lowercase form is listed, together
//! with the string it folds to.

/// The characters whose full case folding differs from their lowercase form.
pub static CASE_FOLDING: &[(char, &str)] = &[
"""

FOOTER = "];\n\n/// Fold a character to the string the specification compares labels with.\n///\n/// Most characters simply fold to their lowercase form; the few that do not\n/// are listed in the table.\npub fn fold(character: char) -> String {\n    match CASE_FOLDING.binary_search_by(|(candidate, _)| (*candidate).cmp(&character)) {\n        Ok(index) => CASE_FOLDING[index].1.to_string(),\n        Err(_) => character.to_lowercase(),\n    }\n}\n"


def escape(value: str) -> str:
    """Write a string as a Rust escape sequence."""
    out = []
    for char in value:
        code = ord(char)
        if char == '"':
            out.append('\\"')
        elif char == "\\":
            out.append("\\\\")
        elif 0x20 <= code < 0x7F:
            out.append(char)
        else:
            out.append(f"\\u{{{code:x}}}")
    return "".join(out)


def main() -> None:
    entries = []
    for code in range(0x110000):
        char = chr(code)
        folded = char.casefold()
        if folded != char.lower():
            entries.append((char, folded))
    entries.sort()

    lines = [HEADER]
    for char, folded in entries:
        lines.append(f'    (\'{escape(char)}\', "{escape(folded)}"),\n')
    lines.append(FOOTER)

    target = pathlib.Path(__file__).resolve().parent.parent / "crates" / "marktext-core" / "src" / "casefold.rs"
    target.write_text("".join(lines), encoding="utf-8")
    print(f"wrote {len(entries)} entries to {target}")


if __name__ == "__main__":
    main()
